def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    if p == 0 or n < 12 or len(np.unique(y)) < 2 or MAX_DRIVERS < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})
    ids = feats.ids; labs = list(dict.fromkeys(feats.stratum))
    base = np.column_stack([np.ones(n)] + [np.array(feats.stratum) == l for l in labs[1:]])
    def fit(sel, pairs=()):
        A = np.column_stack([base] + [X[:, j] for j in sel] + [X[:, a]*X[:, b] for a,b in pairs])
        b = np.zeros(A.shape[1])
        def value(c):
            z = A @ c
            return float(np.sum(y*z - np.logaddexp(0, z)))
        v = value(b)
        for _ in range(35):
            mu = 1/(1 + np.exp(-np.clip(A @ b, -35, 35))); w = mu*(1-mu) + 1e-8
            H = A.T @ (w[:, None]*A) + 1e-6*np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y-mu)); rate = 1.
            while rate > 1e-5 and value(b+rate*step) < v: rate *= .5
            b += rate*step; nv = value(b)
            if abs(nv-v) < 1e-7: break
            v = nv
        mu = 1/(1 + np.exp(-np.clip(A @ b, -35, 35)))
        return value(b), mu, A
    def ll(sel, pairs=()): return fit(sel, pairs)[0]
    C = X-X.mean(0); C /= np.maximum(np.linalg.norm(C, axis=0), 1e-12)
    R = C.T @ C; strength = np.sum(np.where(abs(R) >= .6, R*R, 0), axis=0)
    sel = []; cur = ll(sel)
    for k in range(MAX_DRIVERS):
        pool = [j for j in range(p) if j not in sel and not any(abs(R[j,s]) >= .95 for s in sel)]
        if not pool: break
        vals = np.array([ll(sel+[j]) for j in pool]); v = float(vals.max())
        if stats.chi2.sf(max(0, 2*(v-cur)), 1) > (.1 if k == 0 else .5)/p: break
        j = pool[int(np.argmax(vals))]
        near = [c for c,t in zip(pool, vals) if abs(R[c,j]) >= .6 and t >= v-1]
        j = max(near, key=lambda c: strength[c]); v = ll(sel+[j])
        if stats.chi2.sf(max(0, 2*(v-cur)), 1) > (.1 if k == 0 else .5)/p: break
        sel.append(j); cur = v
    for _ in range(2):
        for j in list(sel):
            rest = [s for s in sel if s != j]
            pool = [j] + [c for c in range(p) if c not in sel and abs(R[c,j]) >= .6]
            vals = [ll(rest+[c]) for c in pool]; c = pool[int(np.argmax(vals))]
            if max(vals) > cur+2: sel[sel.index(j)] = c; cur = max(vals)
    prods = []; npairs = p*(p+1)//2; _, mu, A = fit(sel)
    w = mu*(1-mu)+1e-8; H = A.T @ (w[:,None]*A)+1e-6*np.eye(A.shape[1]); top = []
    for a in range(p):
        P = X[:,[a]]*X[:,a:]; Q = A.T @ (w[:,None]*P)
        var = np.sum(w[:,None]*P*P, 0)-np.sum(Q*np.linalg.solve(H,Q), 0)
        sc = (P.T @ (y-mu))**2/np.maximum(var, 1e-10)
        top += [(float(sc[i]),a,a+int(i)) for i in np.argsort(-sc)[:12]]
        top = sorted(top, reverse=True)[:12]
    for _, a, b in top:
        parents = set(sel) | {c for pair in prods for c in pair} | {a,b}
        if len(parents) > MAX_DRIVERS or len(prods) >= 2: continue
        mains = sorted(parents); v0 = ll(mains, prods); v1 = ll(mains, prods+[(a,b)])
        if stats.chi2.sf(max(0,2*(v1-v0)), 1) < .001/npairs: prods.append((a,b))
    mains = sorted(set(sel) | {c for pair in prods for c in pair})
    changed = True
    while changed and mains:
        changed = False; cur = ll(mains, prods)
        for j in list(mains):
            rest = [s for s in mains if s != j]
            if stats.chi2.sf(max(0,2*(cur-ll(rest,prods))), 1) > .3/p:
                mains = rest; changed = True; break
    cur = ll(mains, prods)
    gains = {j: cur-ll([s for s in mains if s != j],prods) for j in mains}
    for a,b in prods:
        g = cur-ll(mains,[pair for pair in prods if pair != (a,b)])
        for j in (a,b): gains[j] = max(gains.get(j,0),g)
    drivers = sorted(gains, key=lambda j: -gains[j])[:MAX_DRIVERS]
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in mains),
                  products=tuple((ids[a],ids[b]) for a,b in prods), loadings={})

